import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { alignSegments, similarity } from "./segment-alignment.ts";

// Expected results were generated by unmodified Python upstream, not this port.
const fixture = JSON.parse(
  readFileSync(
    new URL("./fixtures/upstream-parity.json", import.meta.url),
    "utf8",
  ),
);
test("character ratios agree with pinned upstream including autojunk and Unicode", () => {
  for (const { a, b, score } of fixture.pairs)
    assert.equal(similarity(a, b), score);
});
test("pairing 1/window 4 results agree with pinned upstream on synthetic segments", () => {
  for (const { segments, lyrics, expected } of fixture.cases) {
    const rows = alignSegments(segments, lyrics, 1).map((row) => ({
      line: row.line,
      start: row.start,
      end: row.end,
      score: row.score,
      matched: row.matched,
    }));
    assert.deepEqual(rows, expected);
  }
});
